(function(){'use strict';const api=window.AvalonOverlay,$=id=>document.getElementById(id);let portal=null;function timer(){const e=$('portal-timer');e.hidden=!portal;if(!portal)return;const seconds=portal.expires===null?null:Math.max(0,Math.floor((portal.expires-Date.now())/1000));e.textContent='Из '+portal.from+' · '+(seconds===null?'таймер не прочитан':seconds===0?'время истекло':'до закрытия '+Math.floor(seconds/3600)+' ч '+Math.floor(seconds%3600/60)+' мин '+seconds%60+' с');}setInterval(timer,1000);function paint({zone:z,portal:p}){if(!z)return;portal=p||null;timer();$('zone-name').textContent=z.name;$('zone-meta').textContent='T'+AvalonMath.zoneLabel(z)+' · '+AvalonMath.worlds[z.world];const img=new Image();img.alt='Карта '+z.name;img.src='avalon-local/'+encodeURIComponent(z.image);$('map').replaceChildren(img);$('features').textContent=z.resources.map(r=>AvalonMath.resources[r.type]+' T'+r.max_tier).join(' · ')+'\n'+z.chests.map(c=>(AvalonMath.chests[c.type]||c.type)+' ×'+c.count).join(' · ');}api.onZone(paint);api.state().then(paint);$('close').onclick=()=>api.control('close');$('pin').onclick=async()=>{const state=await api.control('pin');$('pin').setAttribute('aria-pressed',String(state.pinned));};})();
